"""Minimal psycopg-shaped client for Neon's SQL-over-HTTP endpoint (HTTPS/443).

Neon ships no official Python HTTP driver, so this speaks the same protocol as the official
`@neondatabase/serverless` neon() function: POST https://<endpoint-host>/sql with header
`Neon-Connection-String`, body {query, params} for one statement or {queries:[...]} for a
non-interactive transaction. Each request is its own transaction (autocommit semantics);
session state (search_path, application_name) is re-applied per request via SET LOCAL.
The connection URL is only ever sent as a header and never printed or logged.
"""
from __future__ import annotations
import json, re, time, urllib.error, urllib.parse, urllib.request

_PCT = re.compile(r"%s")
NUMERIC_OIDS = {1700}
INT_OIDS = {20, 21, 23, 26}

def _to_dollar(sql: str) -> str:
    n = [0]
    def rep(_):
        n[0] += 1
        return f"${n[0]}"
    return _PCT.sub(rep, sql).replace("%%", "%")

def split_statements(sql: str) -> list[str]:
    """Split on top-level ';' (respects quotes, comments, $$ bodies)."""
    out, buf, i, q = [], [], 0, None
    while i < len(sql):
        c = sql[i]
        if q:
            if sql.startswith(q, i):
                buf.append(q); i += len(q); q = None; continue
        elif c in ("'", '"'):
            q = c
        elif sql.startswith("$$", i):
            q = "$$"; buf.append("$$"); i += 2; continue
        elif sql.startswith("--", i):
            j = sql.find("\n", i); j = len(sql) if j < 0 else j
            buf.append(sql[i:j]); i = j; continue
        elif c == ";":
            s = "".join(buf).strip()
            if s: out.append(s)
            buf = []; i += 1; continue
        buf.append(c); i += 1
    s = "".join(buf).strip()
    if s: out.append(s)
    return out

