        fields = res.get("fields") or []
        conv = [(float if f["dataTypeID"] in NUMERIC_OIDS else int if f["dataTypeID"] in INT_OIDS else None) for f in fields]
        self.rows = [tuple(c(v) if (c and v is not None) else v for c, v in zip(conv, r)) for r in res.get("rows") or []]
        self.description = [(f["name"],) for f in fields]
        return self
